// The disk functions and their tangents: out = (radius, omega, inner, outer), tout[4 d + j].
template <typename Real, int P>
RM_HD inline void disk_jvp(const Real x[4], const Real* params, const Real* dx, const Real* dparams,
                           Real out[4], Real* tout) {
  (void)x;
  (void)params;
  (void)dx;
  (void)dparams;
  constexpr int NP = 2;
  (void)NP;
  const Real t10 = x[1] * x[1];
  const Real t11 = x[2] * x[2];
  const Real t13 = x[3] * x[3];
  const Real t8 = params[0] * params[1];
  const Real t15 = t8 * t8;
  const Real t17 = t15 * Real(-1.0);
  const Real t18 = t10 + t11 + t13 + t17;
  const Real t19 = t18 * t18;
  const Real t22 = t13 * t15 * Real(4.0);
  const Real t23 = t19 + t22;
  const Real t24 = sqrt(t23);
  const Real t25 = t10 + t11 + t13 + t17 + t24;
  const Real t27 = t25 * Real(0.5);
  const Real t28 = sqrt(t27);
  const Real t97 = sqrt(params[0]);
  const Real t99 = t28 * sqrt(t28);
  const Real t100 = params[0] * params[1] * t97;
  const Real t101 = t99 + t100;
  const Real t102 = Real(1.0) / (t101);
  const Real t103 = t97 * t102;
  const Real t80 = params[1] * params[1];
  const Real t93 = Real(3.0) * t80;
  const Real t81 = Real(-1.0) * t80;
  const Real t82 = Real(1.0) + t81;
  const Real t84 = pow(t82, Real(0.3333333333333333));
  const Real t85 = Real(1.0) + params[1];
  const Real t86 = pow(t85, Real(0.3333333333333333));
  const Real t87 = params[1] * Real(-1.0);
  const Real t88 = Real(1.0) + t87;
  const Real t89 = pow(t88, Real(0.3333333333333333));
  const Real t90 = t86 + t89;
  const Real t91 = t84 * t90;
  const Real t92 = Real(1.0) + t91;
  const Real t94 = t92 * t92;
  const Real t95 = t93 + t94;
  const Real t96 = sqrt(t95);
  const Real t105 = Real(-1.0) * t92;
  const Real t106 = Real(3.0) + t105;
  const Real t108 = Real(2.0) * t96;
  const Real t109 = Real(4.0) + t91 + t108;
  const Real t110 = t106 * t109;
  const Real t111 = sqrt(t110);
  const Real t112 = Real(-1.0) * t111;
  const Real t113 = Real(3.0) + t96 + t112;
  const Real t114 = params[0] * t113;
  const Real t116 = params[0] * Real(20.0);
  const Real t49 = Real(1.0) / (t28);
  const Real t118 = Real(1.0) / (t24);
  const Real t1511 = Real(1.0) / (t97);
  const Real t1514 = Real(1.0) / (t101 * t101);
  const Real t1515 = sqrt(t28);
  const Real t1529 = pow(t82, Real(-0.6666666666666667));
  const Real t1534 = pow(t85, Real(-0.6666666666666667));
  const Real t1536 = pow(t88, Real(-0.6666666666666667));
  const Real t1545 = Real(1.0) / (t96);
  const Real t1553 = Real(1.0) / (t111);
  out[0] = t28;
  out[1] = t103;
  out[2] = t114;
  out[3] = t116;
RM_UNROLL
  for (int d = 0; d < P; ++d) {
    const Real d354 = x[1] * Real(2.0) * dx[4 * d + 1];
    const Real d356 = x[2] * Real(2.0) * dx[4 * d + 2];
    const Real d358 = x[3] * Real(2.0) * dx[4 * d + 3];
    const Real d359 = params[1] * dparams[NP * d + 0];
    const Real d361 = params[0] * dparams[NP * d + 1];
    const Real d362 = d359 + d361;
    const Real d364 = params[0] * params[1] * Real(-2.0) * d362;
    const Real d365 = d354 + d356 + d358 + d364;
    const Real d366 = Real(2.0) * t18 * d365;
    const Real d367 = x[3] * t15 * Real(8.0) * dx[4 * d + 3];
    const Real d368 = params[0] * params[1] * t13 * Real(8.0) * d362;
    const Real d370 = d366 + d367 + d368;
    const Real d371 = Real(0.5) * t118 * d370;
    const Real d372 = d354 + d356 + d358 + d364 + d371;
    const Real d374 = t49 * Real(0.25) * d372;
    const Real d1513 = Real(0.5) * t102 * dparams[NP * d + 0] * t1511;
    const Real d1516 = t49 * d372 * Real(0.375) * t1515;
    const Real d1517 = params[1] * t97 * dparams[NP * d + 0];
    const Real d1518 = params[0] * t97 * dparams[NP * d + 1];
    const Real d1519 = params[0] * params[1] * Real(0.5) * dparams[NP * d + 0] * t1511;
    const Real d1521 = d1516 + d1517 + d1518 + d1519;
    const Real d1523 = Real(-1.0) * t97 * t1514 * d1521;
    const Real d1524 = d1513 + d1523;
    const Real d1525 = t113 * dparams[NP * d + 0];
    const Real d1528 = params[1] * dparams[NP * d + 1] * Real(6.0);
    const Real d1533 = params[1] * t90 * dparams[NP * d + 1] * t1529 * Real(-0.6666666666666666);
    const Real d1535 = Real(0.3333333333333333) * dparams[NP * d + 1] * t1534;
    const Real d1539 = dparams[NP * d + 1] * t1536 * Real(-0.3333333333333333);
    const Real d1540 = d1535 + d1539;
    const Real d1541 = t84 * d1540;
    const Real d1542 = d1533 + d1541;
    const Real d1543 = Real(2.0) * t92 * d1542;
    const Real d1544 = d1528 + d1543;
    const Real d1546 = Real(0.5) * d1544 * t1545;
    const Real d1548 = Real(-1.0) * t109 * d1542;
    const Real d1549 = d1544 * t1545;
    const Real d1550 = d1533 + d1541 + d1549;
    const Real d1551 = t106 * d1550;
    const Real d1552 = d1548 + d1551;
    const Real d1555 = Real(-0.5) * d1552 * t1553;
    const Real d1556 = d1546 + d1555;
    const Real d1557 = params[0] * d1556;
    const Real d1558 = d1525 + d1557;
    const Real d1559 = Real(20.0) * dparams[NP * d + 0];
    tout[4 * d + 0] = d374;
    tout[4 * d + 1] = d1524;
    tout[4 * d + 2] = d1558;
    tout[4 * d + 3] = d1559;
  }
}

// The functions above as one type, so generic code can take the metric as a
// template parameter (rm::trace_ray<rm::kerr::Metric>(...)).
struct Metric {
  static constexpr int PARAM_COUNT = 2;
  static constexpr bool HAS_HORIZON = true;
  static constexpr bool HAS_DISK = true;
  template <typename Real>
  RM_HD static void eval(const Real x[4], const Real* p, Real g[16], Real dg[64]) { metric_eval(x, p, g, dg); }
  template <typename Real>
  RM_HD static Real rhs(const Real y[8], const Real* p, Real dy[8]) { return kerr::geodesic_rhs(y, p, dy); }
  template <typename Real>
  RM_HD static Real horizon_value(const Real x[4], const Real* p) { return kerr::horizon_value(x, p); }
  template <typename Real>
  RM_HD static Real disk_radius(const Real x[4], const Real* p) { return kerr::disk_radius(x, p); }
  template <typename Real>
  RM_HD static Real disk_omega(const Real x[4], const Real* p) { return kerr::disk_omega(x, p); }
  template <typename Real>
  RM_HD static Real disk_inner(const Real x[4], const Real* p) { return kerr::disk_inner(x, p); }
  template <typename Real>
  RM_HD static Real disk_outer(const Real x[4], const Real* p) { return kerr::disk_outer(x, p); }
  template <typename Real>
  RM_HD static Real length_scale(const Real x[4], const Real* p) { return kerr::length_scale(x, p); }
  template <typename Real, int P>
  RM_HD static void jvp(const Real x[4], const Real* p, const Real* dx, const Real* dp, Real g[16], Real dg[64], Real* tg, Real* tdg) {
    kerr::metric_jvp<Real, P>(x, p, dx, dp, g, dg, tg, tdg);
  }
  template <typename Real, int P>
  RM_HD static void disk_jvp(const Real x[4], const Real* p, const Real* dx, const Real* dp, Real out[4], Real* tout) {
    kerr::disk_jvp<Real, P>(x, p, dx, dp, out, tout);
  }
};

